package e.e.a;
import android.content.*;import android.graphics.*;import android.preference.PreferenceManager;import android.view.*;import java.util.*;

/** Incremental live overlay. The existing appearance preferences and font helper are shared. */
final class NicoliveCommentsView extends View {
 static final class Item {final NicoliveData.Chat chat;final long start;final int lane;final float width;Item(NicoliveData.Chat c,long s,int l,float w){chat=c;start=s;lane=l;width=w;}}
 final ArrayList<Item> items=new ArrayList<Item>();final Paint paint=new Paint(3);final Paint outline=new Paint(3);final long[][] nextLane=new long[3][20];NicoliveService service;boolean enabled=true;int sequence,rows=10,opacity=100,shadow=5;float percent=1;long settingsAt,durationMs=5000;final SharedPreferences prefs;
 NicoliveCommentsView(Context c){super(c);prefs=PreferenceManager.getDefaultSharedPreferences(c);refreshSettings();setWillNotDraw(false);setClickable(false);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);outline.setColor(Color.BLACK);outline.setStyle(Paint.Style.STROKE);outline.setStrokeJoin(Paint.Join.ROUND);}
 void clear(){items.clear();for(long[] a:nextLane)Arrays.fill(a,0);invalidate();}
 void add(NicoliveData.Chat c,long epoch){if(!enabled||getWidth()==0||items.size()>=80)return;refreshSettings();int pos=c.position==1?1:c.position==2?2:0;int lane=-1;for(int i=0;i<rows;i++)if(nextLane[pos][i]<=epoch){lane=i;break;}if(lane<0)return;style(c);float width=paint.measureText(c.text);long duration=duration();nextLane[pos][lane]=epoch+(pos==0?Math.min(duration,Math.max(800,(long)(duration*(width+20)/(getWidth()+width)))):duration);items.add(new Item(c,epoch,lane,width));postInvalidateOnAnimation();}
 void refreshSettings(){long now=android.os.SystemClock.uptimeMillis();if(settingsAt>0&&now-settingsAt<500)return;settingsAt=now;rows=Math.max(1,Math.min(20,prefs.getInt("comment_rows",10)));durationMs=1000L*Math.max(1,Math.min(20,prefs.getInt("comment_duration_seconds",5)));percent=Math.max(10,Math.min(200,prefs.getInt("comment_size_percent",100)))/100f;opacity=Math.max(0,Math.min(100,prefs.getInt("comment_opacity_percent",100)));shadow=Math.max(0,prefs.getInt("comment_shadow_tenths",5));}
 long duration(){return durationMs;}
 void style(NicoliveData.Chat c){float base=Math.max(NicoliveUi.dp(getContext(),12),getHeight()/11f)*percent;paint.setTextSize(base*(c.size==1?.7f:c.size==2?1.3f:1));CommentStyle.apply(paint,getContext());paint.setColor(c.color);paint.setAlpha((int)(255*opacity/100f*(c.translucent?.5f:1)));outline.setTextSize(paint.getTextSize());outline.setTypeface(paint.getTypeface());outline.setStrokeWidth(Math.max(1,NicoliveUi.dp(getContext(),shadow/10f)));outline.setAlpha(paint.getAlpha());}
 @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);if(!enabled||service==null||!service.playing())return;long now=service.playbackEpoch();if(now<=0)return;refreshSettings();long duration=duration();float step=getHeight()/(float)rows;Iterator<Item> it=items.iterator();while(it.hasNext()){Item item=it.next();long elapsed=now-item.start;if(elapsed>duration){it.remove();continue;}if(elapsed<0)continue;style(item.chat);float x=item.chat.position==0?getWidth()-(getWidth()+item.width)*elapsed/duration:(getWidth()-item.width)/2;float y=item.chat.position==1?getHeight()-item.lane*step-5:item.lane*step+paint.getTextSize();if(shadow>0)CommentOutlineOpacity.drawLive(canvas,item.chat.text,x,y,outline,paint);else canvas.drawText(item.chat.text,x,y,paint);}if(!items.isEmpty())postInvalidateOnAnimation();}
}
